//! Ordinary source tests for the bounded scalar consumer. Candidate only: UNRUN.
//!
//! S01/S02 rule sequences transcribe the frozen hand-derived oracle
//! `models/sherlock/oracles/source-normal-prefixes.json` (34 and 32 charged
//! edges, then free line-80 publication). Hostile sequences are hand-derived
//! from the main.k line numbers transcribed in `reference.rs`; they are not
//! generated by the machine. Bound totals pin this consumer's stated formulas.
use super::*;

const WEIGHTED: &str = include_str!("source_adapter_fixtures/weighted-total.mori");
const THRESHOLD: &str = include_str!("source_adapter_fixtures/threshold-check.mori");

const S01_LINES: [usize; 35] = [
    131, 135, 102, 177, 102, 181, 200, 204, 208, 135, 114, 135, 117, 135, 108, 149, 108, 153, 223,
    145, 114, 135, 117, 135, 108, 149, 102, 153, 223, 145, 108, 195, 195, 185, 80,
];
const S02_LINES: [usize; 33] = [
    131, 135, 102, 177, 102, 181, 200, 204, 208, 135, 114, 135, 117, 135, 108, 149, 108, 153, 223,
    145, 114, 135, 120, 135, 108, 157, 223, 145, 108, 195, 195, 185, 80,
];

// Test-local admission choices, not defaults for any consumer.
fn bounds(stack_limit: usize) -> HostObservationBounds {
    HostObservationBounds {
        max_source_actions: 8,
        max_source_expressions: 64,
        max_source_statements: 16,
        max_scalar_arguments: 4,
        max_projection_occurrences: 64,
        max_ast_nesting: 16,
        stack_limit,
        max_step_records: 64,
        max_retained_slots: 1 << 20,
    }
}

fn lines(observation: &BoundedSourceObservation) -> Vec<usize> {
    observation
        .records
        .iter()
        .map(|record| record.rule_start_line)
        .collect()
}

fn joined(prefix: &[usize], tail: &[usize]) -> Vec<usize> {
    prefix.iter().chain(tail).copied().collect()
}

fn exceeded(measure: HostMeasure, required: Option<u128>, bound: u128) -> HostObservationRefusal {
    HostObservationRefusal::Exceeded {
        measure,
        required,
        bound,
    }
}

fn hostile_core(expressions: Vec<crate::Expr>, action: crate::Action) -> crate::Program {
    crate::Program {
        language: crate::LANGUAGE.into(),
        semantics: crate::SEMANTICS.into(),
        name: "Hostile".into(),
        states: vec![],
        assets: vec![],
        expressions,
        actions: vec![action],
    }
}

/// Records chain, charges and retained identity common to every admitted run.
fn assert_complete(observation: &BoundedSourceObservation, fuel: u128, stack_limit: usize) {
    let records = &observation.records;
    assert!(!records.is_empty());
    assert_eq!(observation.initial, records[0].before);
    assert_eq!(&observation.terminal, &records[records.len() - 1].after);
    for pair in records.windows(2) {
        assert_eq!(pair[0].after, pair[1].before);
    }
    let (last, charged) = records.split_last().unwrap();
    assert!(charged.iter().all(|record| record.charge == 1));
    assert_eq!(last.charge, 0);
    assert_ne!(observation.terminal.outcome, Outcome::Pending);
    assert_eq!(observation.initial.initial_fuel, fuel);
    assert_eq!(observation.initial.remaining_fuel, fuel);
    assert_eq!(observation.terminal.stack_limit, stack_limit);
    assert_eq!(
        observation.terminal.checked_charged_steps(),
        Some(charged.len() as u128)
    );
    assert!(Arc::ptr_eq(
        &observation.program,
        &observation.initial.program
    ));
    assert!(Arc::ptr_eq(
        &observation.program,
        &observation.terminal.program
    ));
    assert!((records.len() as u128) <= observation.extent.step_record_bound);
    assert!(
        records
            .iter()
            .all(|record| (record.after.depth() as u128) <= observation.extent.frame_bound)
    );
    assert_eq!(observation.qualification, QUALIFICATION);
}

#[test]
fn weighted_source_runs_the_actual_projection_to_the_frozen_publication() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    let observation = observe_scalar_action(&source, 0, &args, 34, bounds(8)).unwrap();
    assert_complete(&observation, 34, 8);
    assert_eq!(lines(&observation), S01_LINES);
    assert_eq!(observation.terminal.outcome, Outcome::Done(Value::UInt(39)));
    assert_eq!(observation.terminal.remaining_fuel, 0);
    assert_eq!(
        observation
            .records
            .iter()
            .map(|record| record.after.depth())
            .max(),
        Some(4)
    );
    // The retained report and function are the adapter's own, not a copy.
    let mapped = prepare_scalar_action(&source, 0).unwrap();
    assert_eq!(observation.report, mapped.report);
    assert_eq!(observation.program.functions, vec![mapped.function]);
    assert_eq!(
        *observation.program.entry,
        Expr::Call(
            "quote".into(),
            vec![
                Arc::new(Expr::Literal(Value::UInt(4))),
                Arc::new(Expr::Literal(Value::UInt(9)))
            ]
        )
    );
    // Nine occurrences match the existing adapter test; nesting is let/let/add/var.
    assert_eq!(
        observation.extent,
        HostExtent {
            bounds: bounds(8),
            projected_occurrences: 9,
            ast_nesting_bound: 4,
            observed_ast_nesting: 4,
            step_record_bound: 35,
            frame_bound: 8,
            environment_entry_bound: 4,
            peak_slot_bound: 74 * 11 * 9,
            argument_types_match_inputs: true
        }
    );
}

#[test]
fn threshold_source_publishes_the_frozen_boolean() {
    let source = crate::parse(THRESHOLD).unwrap();
    let args = [Value::UInt(7), Value::UInt(10)];
    let observation = observe_scalar_action(&source, 0, &args, 32, bounds(8)).unwrap();
    assert_complete(&observation, 32, 8);
    assert_eq!(lines(&observation), S02_LINES);
    assert_eq!(
        observation.terminal.outcome,
        Outcome::Done(Value::Bool(false))
    );
    assert_eq!(observation.extent.projected_occurrences, 8);
    assert_eq!(observation.report.occurrences.len(), 8);
}

#[test]
fn fuel_prefixes_keep_existing_exhaustion_and_publication_order() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    let zero = observe_scalar_action(&source, 0, &args, 0, bounds(8)).unwrap();
    assert_complete(&zero, 0, 8);
    assert_eq!(lines(&zero), vec![84]);
    assert_eq!(zero.terminal.outcome, Outcome::Exhausted);
    let short = observe_scalar_action(&source, 0, &args, 33, bounds(8)).unwrap();
    assert_complete(&short, 33, 8);
    assert_eq!(lines(&short), joined(&S01_LINES[..33], &[84]));
    assert_eq!(short.terminal.outcome, Outcome::Exhausted);
    // Publication precedes exhaustion; spare fuel stays unspent.
    let spare = observe_scalar_action(&source, 0, &args, 35, bounds(8)).unwrap();
    assert_complete(&spare, 35, 8);
    assert_eq!(lines(&spare), S01_LINES);
    assert_eq!(spare.terminal.remaining_fuel, 1);
}

#[test]
fn zero_input_action_uses_the_empty_call_rule() {
    let source = crate::parse(
        "language \"moriarty/1\"; agreement Constant { action k() { emit \"k\"(5); } }",
    )
    .unwrap();
    let observation = observe_scalar_action(&source, 0, &[], 7, bounds(8)).unwrap();
    assert_complete(&observation, 7, 8);
    assert_eq!(
        lines(&observation),
        vec![129, 200, 204, 208, 135, 102, 185, 80]
    );
    assert_eq!(observation.terminal.outcome, Outcome::Done(Value::UInt(5)));
}

#[test]
fn frame_cap_is_the_existing_a_outcome_not_a_host_refusal() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    let observation = observe_scalar_action(&source, 0, &args, 34, bounds(3)).unwrap();
    assert_complete(&observation, 34, 3);
    // The fourth simultaneous frame (S01 edge 24) is refused by rule 140.
    assert_eq!(lines(&observation), joined(&S01_LINES[..23], &[140, 82]));
    assert_eq!(observation.terminal.outcome, Outcome::Rejected(4));
    assert!(observation.terminal.outcome.is_resource_limit());
    assert_eq!(observation.terminal.remaining_fuel, 10);
}

#[test]
fn checked_overflow_keeps_the_existing_arithmetic_rejection() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(u128::MAX), Value::UInt(2)];
    let observation = observe_scalar_action(&source, 0, &args, 19, bounds(8)).unwrap();
    assert_complete(&observation, 19, 8);
    assert_eq!(lines(&observation), joined(&S01_LINES[..18], &[225, 82]));
    assert_eq!(observation.terminal.outcome, Outcome::Rejected(10));
    assert!(!observation.terminal.outcome.is_resource_limit());
}

#[test]
fn arity_and_type_mismatches_reach_the_existing_binding_rejection() {
    let source = crate::parse(WEIGHTED).unwrap();
    let short = observe_scalar_action(&source, 0, &[Value::UInt(4)], 7, bounds(8)).unwrap();
    assert_complete(&short, 7, 8);
    assert_eq!(lines(&short), vec![131, 135, 102, 181, 200, 204, 206, 82]);
    assert_eq!(short.terminal.outcome, Outcome::Rejected(8));
    assert!(!short.extent.argument_types_match_inputs);
    let args = [Value::Bool(true), Value::UInt(9)];
    let mistyped = observe_scalar_action(&source, 0, &args, 9, bounds(8)).unwrap();
    assert_complete(&mistyped, 9, 8);
    assert_eq!(
        lines(&mistyped),
        vec![131, 135, 102, 177, 102, 181, 200, 204, 206, 82]
    );
    assert_eq!(mistyped.terminal.outcome, Outcome::Rejected(8));
    assert!(!mistyped.extent.argument_types_match_inputs);
}

#[test]
fn list_and_tree_arguments_are_refused_by_discriminant() {
    let source = crate::parse(WEIGHTED).unwrap();
    let list = [Value::UInt(4), Value::List(vec![1, 2])];
    assert_eq!(
        observe_scalar_action(&source, 0, &list, 34, bounds(8)),
        Err(HostObservationRefusal::NonScalarArgument { index: 1 })
    );
    let tree = [Value::Tree(crate::sherlock::Tree::Leaf(1)), Value::UInt(9)];
    assert_eq!(
        observe_scalar_action(&source, 0, &tree, 34, bounds(8)),
        Err(HostObservationRefusal::NonScalarArgument { index: 0 })
    );
    let wide = [Value::UInt(1), Value::UInt(2), Value::UInt(3)];
    let narrow = HostObservationBounds {
        max_scalar_arguments: 2,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &wide, 34, narrow),
        Err(exceeded(HostMeasure::ScalarArguments, Some(3), 2))
    );
}

#[test]
fn fuel_beyond_the_record_bound_is_refused_before_execution() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    assert_eq!(
        observe_scalar_action(&source, 0, &args, u128::MAX, bounds(8)),
        Err(exceeded(HostMeasure::StepRecords, None, 64))
    );
    let tight = HostObservationBounds {
        max_step_records: 34,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, tight),
        Err(exceeded(HostMeasure::StepRecords, Some(35), 34))
    );
    let exact = HostObservationBounds {
        max_step_records: 35,
        ..bounds(8)
    };
    assert_eq!(
        lines(&observe_scalar_action(&source, 0, &args, 34, exact).unwrap()),
        S01_LINES
    );
}

#[test]
fn retained_slot_bound_is_exact_at_its_boundary_and_caps_stack_limit() {
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    let peak = 74 * 11 * 9;
    let below = HostObservationBounds {
        max_retained_slots: peak - 1,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, below),
        Err(exceeded(HostMeasure::RetainedSlots, Some(peak), peak - 1))
    );
    let at = HostObservationBounds {
        max_retained_slots: peak,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, at)
            .unwrap()
            .extent
            .peak_slot_bound,
        peak
    );
    // An unbounded frame cap counts only the frames fuel can push: min(MAX, 34).
    let uncapped = HostObservationBounds {
        max_retained_slots: peak,
        ..bounds(usize::MAX)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, uncapped),
        Err(exceeded(
            HostMeasure::RetainedSlots,
            Some(74 * 37 * 9),
            peak
        ))
    );
}

#[test]
fn shared_dag_fanout_is_refused_before_preparation() {
    // Linear Core DAG whose unshared projection needs 2^15 - 1 occurrences.
    let mut expressions = vec![crate::Expr::Literal {
        value: crate::Value::UInt(crate::UInt(1)),
    }];
    for i in 0..14u16 {
        expressions.push(crate::Expr::Binary {
            op: crate::BinaryOp::Add,
            lhs: i,
            rhs: i,
        });
    }
    let program = hostile_core(
        expressions,
        crate::Action {
            name: "blow".into(),
            inputs: vec![],
            statements: vec![crate::Statement::Emit {
                name: "out".into(),
                value: 14,
            }],
        },
    );
    crate::validate(&program).unwrap();
    assert_eq!(
        observe_scalar_action(&program, 0, &[], 0, bounds(8)),
        Err(exceeded(
            HostMeasure::ProjectionOccurrences,
            Some(32_767),
            64
        ))
    );
    // A caller bound above the adapter's fixed budget surfaces its own diagnostic.
    let wide = HostObservationBounds {
        max_projection_occurrences: 40_000,
        ..bounds(8)
    };
    let Err(HostObservationRefusal::Projection(diagnostic)) =
        observe_scalar_action(&program, 0, &[], 0, wide)
    else {
        panic!("the adapter budget still applies under a wider caller bound");
    };
    assert_eq!(diagnostic.construct, "projection-occurrence-budget");
    assert_eq!(diagnostic.code, "projection-occurrence-budget-exhausted");
}

#[test]
fn long_let_chain_nesting_is_refused_then_admitted_at_its_bound() {
    // let y1 = x + 1; ... let y40 = y39 + 1; emit "out"(y40).
    let (mut expressions, mut statements) = (vec![], vec![]);
    for i in 1..=40u16 {
        let previous = if i == 1 {
            "x".to_string()
        } else {
            format!("y{}", i - 1)
        };
        let base = 3 * (i - 1);
        expressions.push(crate::Expr::Name { name: previous });
        expressions.push(crate::Expr::Literal {
            value: crate::Value::UInt(crate::UInt(1)),
        });
        expressions.push(crate::Expr::Binary {
            op: crate::BinaryOp::Add,
            lhs: base,
            rhs: base + 1,
        });
        statements.push(crate::Statement::Let {
            name: format!("y{i}"),
            value: base + 2,
        });
    }
    expressions.push(crate::Expr::Name { name: "y40".into() });
    statements.push(crate::Statement::Emit {
        name: "out".into(),
        value: 120,
    });
    let program = hostile_core(
        expressions,
        crate::Action {
            name: "chain".into(),
            inputs: vec![crate::InputDecl {
                name: "x".into(),
                ty: crate::Type::UInt,
            }],
            statements,
        },
    );
    crate::validate(&program).unwrap();
    let base = HostObservationBounds {
        max_source_expressions: 121,
        max_source_statements: 41,
        max_projection_occurrences: 161,
        ..bounds(8)
    };
    let shallow = HostObservationBounds {
        max_ast_nesting: 41,
        ..base
    };
    assert_eq!(
        observe_scalar_action(&program, 0, &[Value::UInt(0)], 0, shallow),
        Err(exceeded(HostMeasure::AstNesting, Some(42), 41))
    );
    let exact = HostObservationBounds {
        max_ast_nesting: 42,
        ..base
    };
    let observation = observe_scalar_action(&program, 0, &[Value::UInt(0)], 0, exact).unwrap();
    assert_complete(&observation, 0, 8);
    assert_eq!(lines(&observation), vec![84]);
    assert_eq!(observation.report.occurrences.len(), 161);
    assert_eq!(
        (
            observation.extent.ast_nesting_bound,
            observation.extent.observed_ast_nesting
        ),
        (42, 42)
    );
}

#[test]
fn source_shape_is_refused_before_core_validation() {
    let expressions = vec![
        crate::Expr::Literal {
            value: crate::Value::UInt(crate::UInt(0))
        };
        9000
    ];
    let program = hostile_core(
        expressions,
        crate::Action {
            name: "big".into(),
            inputs: vec![],
            statements: vec![crate::Statement::Emit {
                name: "out".into(),
                value: 0,
            }],
        },
    );
    assert_eq!(
        observe_scalar_action(&program, 0, &[], 0, bounds(8)),
        Err(exceeded(HostMeasure::SourceExpressions, Some(9000), 64))
    );
    // Within the caller bound, the actual Core validation error is retained.
    let wide = HostObservationBounds {
        max_source_expressions: 10_000,
        ..bounds(8)
    };
    let Err(HostObservationRefusal::CoreValidation(error)) =
        observe_scalar_action(&program, 0, &[], 0, wide)
    else {
        panic!("Core rejects more than MAX_EXPRESSIONS");
    };
    assert_eq!(error.code, "mori::core::bound");
    let source = crate::parse(WEIGHTED).unwrap();
    let args = [Value::UInt(4), Value::UInt(9)];
    let few = HostObservationBounds {
        max_source_statements: 2,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, few),
        Err(exceeded(HostMeasure::SourceStatements, Some(3), 2))
    );
    let one = HostObservationBounds {
        max_source_actions: 0,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 34, one),
        Err(exceeded(HostMeasure::SourceActions, Some(1), 0))
    );
}

#[test]
fn lowered_gt_runs_the_actual_projection_to_its_publication() {
    let source = crate::parse("language \"moriarty/1\"; agreement Outside { action compare(a: UInt, b: UInt) { emit \"greater\"(a > b); } }").unwrap();
    let args = [Value::UInt(2), Value::UInt(1)];
    let observation = observe_scalar_action(&source, 0, &args, 28, bounds(8)).unwrap();
    assert_complete(&observation, 28, 8);
    // Hand-derived from reference.rs, not an independent oracle: the S01 call
    // prefix, then Let($0l, a, Let($0r, b, Binary(Lt, Var($0r), Var($0l)))).
    assert_eq!(
        lines(&observation),
        joined(
            &S01_LINES[..10],
            &[
                114, 135, 108, 145, 114, 135, 108, 145, 117, 135, 108, 149, 108, 153, 223, 195,
                195, 185, 80
            ]
        )
    );
    assert_eq!(
        observation.terminal.outcome,
        Outcome::Done(Value::Bool(true))
    );
    assert_eq!(observation.terminal.remaining_fuel, 0);
    assert_eq!(
        observation
            .records
            .iter()
            .map(|record| record.after.depth())
            .max(),
        Some(4)
    );
    let mapped = prepare_scalar_action(&source, 0).unwrap();
    assert_eq!(observation.report, mapped.report);
    assert_eq!(observation.program.functions, vec![mapped.function]);
    // Seven generated nodes; two synthetic binders join the two parameters.
    let peak = 62 * 11 * 9;
    assert_eq!(
        observation.extent,
        HostExtent {
            bounds: bounds(8),
            projected_occurrences: 7,
            ast_nesting_bound: 4,
            observed_ast_nesting: 4,
            step_record_bound: 29,
            frame_bound: 8,
            environment_entry_bound: 4,
            peak_slot_bound: peak,
            argument_types_match_inputs: true
        }
    );
    // The former one-per-Binary count (3, nesting 2) fit these bounds and refused
    // only after preparation; the exact count refuses before it.
    let few = HostObservationBounds {
        max_projection_occurrences: 6,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 28, few),
        Err(exceeded(HostMeasure::ProjectionOccurrences, Some(7), 6))
    );
    let shallow = HostObservationBounds {
        max_ast_nesting: 3,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 28, shallow),
        Err(exceeded(HostMeasure::AstNesting, Some(4), 3))
    );
    let below = HostObservationBounds {
        max_retained_slots: peak - 1,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &args, 28, below),
        Err(exceeded(HostMeasure::RetainedSlots, Some(peak), peak - 1))
    );
}

#[test]
fn unsupported_statements_and_missing_actions_stay_metadata() {
    let source = crate::parse("language \"moriarty/1\"; agreement Outside { action compare(a: UInt, b: UInt) { requires a > b; emit \"greater\"(a > b); } }").unwrap();
    let args = [Value::UInt(2), Value::UInt(1)];
    let Err(HostObservationRefusal::Projection(diagnostic)) =
        observe_scalar_action(&source, 0, &args, 8, bounds(8))
    else {
        panic!("requires has no scalar projection");
    };
    assert_eq!(diagnostic.construct, "requires");
    assert_eq!(diagnostic.code, "unsupported-projection");
    assert_eq!(diagnostic.statement_index, Some(0));
    // The Core program itself remains valid source.
    crate::validate(&source).unwrap();
    assert_eq!(
        observe_scalar_action(&source, 1, &args, 8, bounds(8)),
        Err(HostObservationRefusal::NoSuchAction {
            action_index: 1,
            action_count: 1
        })
    );
}

#[test]
fn every_core_scalar_operator_is_counted_exactly_before_preparation() {
    // (spelling, type, nodes, nesting, synthetic binders) of `left OP right`,
    // hand-derived from the adapter's lowering table over two Name leaves.
    let cases = [
        ("+", "UInt", 3, 2, 0),
        ("-", "UInt", 3, 2, 0),
        ("*", "UInt", 3, 2, 0),
        ("==", "UInt", 3, 2, 0),
        ("<", "UInt", 3, 2, 0),
        ("not =", "UInt", 4, 3, 0),
        (">=", "UInt", 4, 3, 0),
        (">", "UInt", 7, 4, 2),
        ("<=", "UInt", 8, 5, 2),
        ("and", "Bool", 8, 4, 2),
        ("or", "Bool", 8, 4, 2),
    ];
    for (spelling, ty, nodes, nesting, binders) in cases {
        let source = crate::parse(&format!("language \"moriarty/1\"; agreement Operators {{ action inspect(left: {ty}, right: {ty}) {{ emit \"value\"(left {spelling} right); }} }}")).unwrap();
        let args = if ty == "UInt" {
            [Value::UInt(3), Value::UInt(5)]
        } else {
            [Value::Bool(true), Value::Bool(false)]
        };
        let exact = HostObservationBounds {
            max_projection_occurrences: nodes,
            max_ast_nesting: nesting,
            ..bounds(8)
        };
        let observation = observe_scalar_action(&source, 0, &args, 0, exact).unwrap();
        assert_complete(&observation, 0, 8);
        assert_eq!(lines(&observation), vec![84]);
        assert_eq!(observation.report.occurrences.len(), nodes);
        assert_eq!(observation.extent.projected_occurrences, nodes as u128);
        assert_eq!(
            (
                observation.extent.ast_nesting_bound,
                observation.extent.observed_ast_nesting
            ),
            (nesting as u128, nesting)
        );
        assert_eq!(observation.extent.environment_entry_bound, 2 + binders);
        // Fuel 0: six snapshot units of three units, each entries + 2 * 2 + 1.
        assert_eq!(
            observation.extent.peak_slot_bound,
            6 * 3 * (2 + binders + 5)
        );
        let fewer = HostObservationBounds {
            max_projection_occurrences: nodes - 1,
            ..exact
        };
        assert_eq!(
            observe_scalar_action(&source, 0, &args, 0, fewer),
            Err(exceeded(
                HostMeasure::ProjectionOccurrences,
                Some(nodes as u128),
                nodes as u128 - 1
            ))
        );
        let shallower = HostObservationBounds {
            max_ast_nesting: nesting - 1,
            ..exact
        };
        assert_eq!(
            observe_scalar_action(&source, 0, &args, 0, shallower),
            Err(exceeded(
                HostMeasure::AstNesting,
                Some(nesting as u128),
                nesting as u128 - 1
            ))
        );
    }
}

#[test]
fn zero_input_lowered_conditional_counts_both_branch_references() {
    let source = crate::parse(
        "language \"moriarty/1\"; agreement Constant { action k() { emit \"k\"(true and false); } }").unwrap();
    let observation = observe_scalar_action(&source, 0, &[], 21, bounds(8)).unwrap();
    assert_complete(&observation, 21, 8);
    // Hand-derived from reference.rs, not an independent oracle:
    // Let($0l, true, Let($0r, false, If(Var($0l), Var($0r), false))).
    assert_eq!(
        lines(&observation),
        vec![
            129, 200, 204, 208, 135, 114, 135, 102, 145, 114, 135, 102, 145, 123, 135, 108, 161,
            108, 195, 195, 185, 80
        ]
    );
    assert_eq!(
        observation.terminal.outcome,
        Outcome::Done(Value::Bool(false))
    );
    assert_eq!(
        observation
            .records
            .iter()
            .map(|record| record.after.depth())
            .max(),
        Some(4)
    );
    // An If frame holds an environment plus two branch references: with no
    // parameters each unit is entries + 2, not entries + 1.
    let peak = 48 * 11 * 4;
    assert_eq!(
        (
            observation.extent.environment_entry_bound,
            observation.extent.peak_slot_bound
        ),
        (2, peak)
    );
    let below = HostObservationBounds {
        max_retained_slots: peak - 1,
        ..bounds(8)
    };
    assert_eq!(
        observe_scalar_action(&source, 0, &[], 21, below),
        Err(exceeded(HostMeasure::RetainedSlots, Some(peak), peak - 1))
    );
}

#[test]
fn lowered_dag_fanout_is_counted_exactly_before_preparation() {
    // e0 = true; e(k+1) = e(k) or e(k). Unshared: nodes 7 * 2^k - 6, nesting
    // 2k + 2, and 2^k - 1 lowered Ors with two synthetic binders each.
    let mut expressions = vec![crate::Expr::Literal {
        value: crate::Value::Bool(true),
    }];
    for i in 0..4u16 {
        expressions.push(crate::Expr::Binary {
            op: crate::BinaryOp::Or,
            lhs: i,
            rhs: i,
        });
    }
    let program = hostile_core(
        expressions,
        crate::Action {
            name: "blow".into(),
            inputs: vec![],
            statements: vec![crate::Statement::Emit {
                name: "out".into(),
                value: 4,
            }],
        },
    );
    crate::validate(&program).unwrap();
    // The former one-per-Binary count (31, nesting 5) fit these bounds and
    // refused only after preparation had allocated all 106 occurrences.
    assert_eq!(
        observe_scalar_action(&program, 0, &[], 0, bounds(8)),
        Err(exceeded(HostMeasure::ProjectionOccurrences, Some(106), 64))
    );
    let wide = HostObservationBounds {
        max_projection_occurrences: 106,
        ..bounds(8)
    };
    let shallow = HostObservationBounds {
        max_ast_nesting: 9,
        ..wide
    };
    assert_eq!(
        observe_scalar_action(&program, 0, &[], 0, shallow),
        Err(exceeded(HostMeasure::AstNesting, Some(10), 9))
    );
    let observation = observe_scalar_action(&program, 0, &[], 0, wide).unwrap();
    assert_complete(&observation, 0, 8);
    assert_eq!(lines(&observation), vec![84]);
    assert_eq!(observation.report.occurrences.len(), 106);
    assert_eq!(
        (
            observation.extent.ast_nesting_bound,
            observation.extent.observed_ast_nesting
        ),
        (10, 10)
    );
    // Thirty distinct synthetic binders; with an If and no parameters each unit is entries + 2.
    assert_eq!(observation.extent.environment_entry_bound, 30);
    assert_eq!(observation.extent.peak_slot_bound, 6 * 3 * 32);
}
